from money import split_amount


def test_even_split():
    assert split_amount(90, 3) == [30, 30, 30]


def test_one_part():
    assert split_amount(55, 1) == [55]


def test_remainder_goes_to_first_shares():
    assert split_amount(100, 3) == [34, 33, 33]


def test_shares_add_up():
    for total in range(0, 200):
        for parts in range(1, 9):
            assert sum(split_amount(total, parts)) == total


def test_zero_parts_raises():
    import pytest
    with pytest.raises(ValueError):
        split_amount(100, 0)

